$static$;
SELECT set_config('step7c.checks50', (coalesce(nullif(current_setting('step7c.checks50', true), ''), '0')::integer + 139)::text, false) AS counted \gset x_
DO $fp$
DECLARE
    t text;
    v text;
BEGIN
    FOREACH t IN ARRAY ARRAY['flat_numeric', 'flat_numeric_btree', 'flat_geom', 'flat_geom_gist', 'flat_geom_spgist', 'flat_geom_brin', 'flat_geog', 'flat_geog_gist', 'flat_geog_spgist', 'jsonb_doc', 'jsonb_doc_expr', 'jsonb_geom', 'jsonb_geom_gist', 'jsonb_geog', 'jsonb_geog_gist'] LOOP
        EXECUTE format('SELECT md5(string_agg(x::text, chr(10) ORDER BY x.log_id)) FROM log_regex_gis.%I AS x', t) INTO v;
        RAISE NOTICE '@@FP %: %', t, v;
    END LOOP;
END
