            ELSE
                v_failed := v_failed + 1;
                RAISE WARNING 'C-03:%/% FAIL  result = plain-SQL oracle: expected %, actual %', chk.id, v_mode, v_expected, v_actual;
            END IF;
        END LOOP;
    END LOOP;
    PERFORM set_config('enable_seqscan', 'on', true);
    PERFORM set_config('enable_indexscan', 'on', true);
    PERFORM set_config('enable_bitmapscan', 'on', true);
    PERFORM set_config('step7c.verify50', v_failed::text, false);
    PERFORM set_config('step7c.checks50', v_checks::text, false);
END
$matrix$;
DO $info$
BEGIN
    RAISE NOTICE 'INFO K1 (geography, metres) vs K1g (geometry, degrees) at Reykjavik: common log_ids %', (SELECT count(*) FROM (SELECT log_id FROM log_regex_gis.flat_geog ORDER BY geog OPERATOR(postgis.<->) postgis.geography(postgis.ST_SetSRID(postgis.ST_MakePoint(-21.9426, 64.1466), 4326)) LIMIT 10) a JOIN (SELECT log_id FROM log_regex_gis.flat_geom ORDER BY geom OPERATOR(postgis.<->) postgis.ST_SetSRID(postgis.ST_MakePoint(-21.9426, 64.1466), 4326) LIMIT 10) b ON b.log_id = a.log_id);
END
$info$;
DO $verdict$
BEGIN
    IF current_setting('step7c.verify50')::integer > 0 THEN
        RAISE EXCEPTION 'sql/50 phase after FAILED: % of % checks', current_setting('step7c.verify50'), current_setting('step7c.checks50') USING ERRCODE = 'LR024';
    END IF;
    IF current_setting('step7c.checks50')::integer <> 745 THEN
        RAISE EXCEPTION 'sql/50 phase after: % checks ran, 745 expected', current_setting('step7c.checks50') USING ERRCODE = 'LR024';
    END IF;
    RAISE NOTICE 'sql/50 phase after PASSED: all 745 checks';
END
$verdict$;
DO $harness$ BEGIN RAISE NOTICE 'Step 7C harness PASSED: 10 builds, ANALYZE, sql/50 phase after inside one transaction'; END $harness$;
ROLLBACK;
